-- ZASHM final launch read-only checks. SELECT only. Paste all and Run.

-- 1) SELECT c.relname, pg_get_userbyid(c.relowner) AS owner, c.relkind, c.relrowsecur...
SELECT c.relname, pg_get_userbyid(c.relowner) AS owner, c.relkind, c.relrowsecurity AS rls_enabled, c.relforcerowsecurity AS rls_forced FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('products', 'products_public', 'users', 'orders', 'coupons') ORDER BY c.relname;

-- 2) SELECT pg_get_viewdef('public.products_public'::regclass, true) AS view_definiti...
SELECT pg_get_viewdef('public.products_public'::regclass, true) AS view_definition;

-- 3) SELECT column_name, data_type FROM information_schema.columns WHERE table_schema...
SELECT column_name, data_type FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'products_public' ORDER BY ordinal_position;

-- 4) SELECT table_name, grantee, privilege_type FROM information_schema.role_table_gr...
SELECT table_name, grantee, privilege_type FROM information_schema.role_table_grants WHERE table_schema = 'public' AND table_name IN ('products', 'products_public') AND grantee IN ('PUBLIC', 'anon', 'authenticated', 'service_role') ORDER BY table_name, grantee, privilege_type;

-- 5) SELECT grantee, column_name, privilege_type FROM information_schema.column_privi...
SELECT grantee, column_name, privilege_type FROM information_schema.column_privileges WHERE table_schema = 'public' AND table_name = 'products' AND grantee IN ('PUBLIC', 'anon', 'authenticated') ORDER BY grantee, column_name, privilege_type;

-- 6) SELECT has_table_privilege('public', 'public.products', 'SELECT') AS public_can_...
SELECT has_table_privilege('public', 'public.products', 'SELECT') AS public_can_read_products, has_table_privilege('anon', 'public.products', 'SELECT') AS anon_can_read_products, has_table_privilege('authenticated', 'public.products', 'SELECT') AS auth_can_read_products, has_any_column_privilege('anon', 'public.products', 'SELECT') AS anon_has_column_read, has_any_column_privilege('authenticated', 'public.products', 'SELECT') AS auth_has_column_read, has_table_privilege('anon', 'public.products_public', 'SELECT') AS anon_can_read_view, has_table_privilege('service_role', 'public.products', 'SELECT') AS service_can_read_products;

-- 7) SELECT n.nspname AS schema, c.relname AS table_name, c.relrowsecurity AS rls_ena...
SELECT n.nspname AS schema, c.relname AS table_name, c.relrowsecurity AS rls_enabled, c.relforcerowsecurity AS rls_forced, count(p.policyname) AS policy_count FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace LEFT JOIN pg_policies p ON p.schemaname = n.nspname AND p.tablename = c.relname WHERE n.nspname = 'public' AND c.relname IN ('products', 'products_public', 'orders', 'users', 'coupons') GROUP BY n.nspname, c.relname, c.relrowsecurity, c.relforcerowsecurity ORDER BY c.relname;

-- 8) SELECT tablename, policyname, permissive, cmd, roles, qual, with_check FROM pg_p...
SELECT tablename, policyname, permissive, cmd, roles, qual, with_check FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('users', 'orders', 'coupons') ORDER BY tablename, policyname;

-- 9) SELECT t.table_name, r.rolname AS role_name, has_table_privilege(r.rolname, form...
SELECT t.table_name, r.rolname AS role_name, has_table_privilege(r.rolname, format('public.%I', t.table_name), 'SELECT') AS can_select, has_table_privilege(r.rolname, format('public.%I', t.table_name), 'INSERT') AS can_insert, has_table_privilege(r.rolname, format('public.%I', t.table_name), 'UPDATE') AS can_update, has_table_privilege(r.rolname, format('public.%I', t.table_name), 'DELETE') AS can_delete, has_table_privilege(r.rolname, format('public.%I', t.table_name), 'TRUNCATE') AS can_truncate, has_table_privilege(r.rolname, format('public.%I', t.table_name), 'REFERENCES') AS can_references, has_table_privilege(r.rolname, format('public.%I', t.table_name), 'TRIGGER') AS can_trigger FROM (VALUES ('users'), ('orders'), ('coupons')) AS t(table_name) CROSS JOIN (VALUES ('anon'), ('authenticated'), ('service_role')) AS r(rolname) ORDER BY t.table_name, r.rolname;

-- 10) SELECT table_name, grantee, column_name, privilege_type FROM information_schema....
SELECT table_name, grantee, column_name, privilege_type FROM information_schema.column_privileges WHERE table_schema = 'public' AND table_name IN ('users', 'orders', 'coupons') AND grantee IN ('PUBLIC', 'anon', 'authenticated') ORDER BY table_name, grantee, column_name, privilege_type;

-- 11) SELECT count(*) FILTER (WHERE active IS TRUE) AS active_products, count(*) FILTE...
SELECT count(*) FILTER (WHERE active IS TRUE) AS active_products, count(*) FILTER (WHERE active IS FALSE) AS inactive_products, count(*) FILTER (WHERE active IS NULL) AS null_active_products, count(*) AS total_products FROM public.products;

-- 12) SELECT count(*) FILTER (WHERE "reservedStock" IS NOT NULL AND "reservedStock" <>...
SELECT count(*) FILTER (WHERE "reservedStock" IS NOT NULL AND "reservedStock" <> 0) AS nonzero_reserved_stock, count(*) AS total_products FROM public.products;

-- 13) SELECT count(*) FILTER (WHERE role = 'admin') AS admins, count(*) FILTER (WHERE ...
SELECT count(*) FILTER (WHERE role = 'admin') AS admins, count(*) FILTER (WHERE role <> 'admin') AS non_admins, count(*) AS total_users FROM public.users;

-- 14) SELECT count(*) AS total_orders, count(*) FILTER (WHERE lower(COALESCE(status, '...
SELECT count(*) AS total_orders, count(*) FILTER (WHERE lower(COALESCE(status, '')) = 'cancelled') AS cancelled_orders FROM public.orders;

-- 15) SELECT count(*) AS total_coupons, count(*) FILTER (WHERE active IS TRUE) AS acti...
SELECT count(*) AS total_coupons, count(*) FILTER (WHERE active IS TRUE) AS active_coupons FROM public.coupons;

-- 16) SELECT name, set_at, note FROM public.zshm_deploy_flags ORDER BY name
SELECT name, set_at, note FROM public.zshm_deploy_flags ORDER BY name;

-- 17) SELECT column_name, data_type, column_default, is_nullable FROM information_sche...
SELECT column_name, data_type, column_default, is_nullable FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'users' AND column_name = 'session_version';

-- 18) SELECT id, public, file_size_limit, allowed_mime_types FROM storage.buckets WHER...
SELECT id, public, file_size_limit, allowed_mime_types FROM storage.buckets WHERE id = 'products';

-- 19) SELECT policyname, cmd, roles, qual, with_check FROM pg_policies WHERE schemanam...
SELECT policyname, cmd, roles, qual, with_check FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND (coalesce(qual, '') LIKE '%products%' OR coalesce(with_check, '') LIKE '%products%') ORDER BY policyname;

-- 20) SELECT policyname, permissive, roles, qual FROM pg_policies WHERE schemaname = '...
SELECT policyname, permissive, roles, qual FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'zshm_products_no_public_listing';

-- 21) SELECT ( SELECT relrowsecurity FROM pg_class WHERE oid = to_regclass('public.zsh...
SELECT ( SELECT relrowsecurity FROM pg_class WHERE oid = to_regclass('public.zshm_rate_limits') ) AS rate_limits_rls_enabled, CASE WHEN to_regclass('public.zshm_rate_limits') IS NULL THEN NULL ELSE has_table_privilege('anon', to_regclass('public.zshm_rate_limits'), 'SELECT') END AS anon_can_read_counters, CASE WHEN to_regprocedure('public.zshm_rate_limit(text,integer,integer,text)') IS NULL THEN NULL ELSE has_function_privilege('anon', to_regprocedure('public.zshm_rate_limit(text,integer,integer,text)'), 'EXECUTE') END AS anon_can_execute_limiter, CASE WHEN to_regprocedure('public.zshm_rate_limit(text,integer,integer,text)') IS NULL THEN NULL ELSE has_function_privilege('service_role', to_regprocedure('public.zshm_rate_limit(text,integer,integer,text)'), 'EXECUTE') END AS service_can_execute_limiter;

-- 22) SELECT pg_get_functiondef( to_regprocedure('public.zshm_rate_limit(text,integer,...
SELECT pg_get_functiondef( to_regprocedure('public.zshm_rate_limit(text,integer,integer,text)') ) AS rate_limit_function_definition WHERE to_regprocedure('public.zshm_rate_limit(text,integer,integer,text)') IS NOT NULL;

-- 23) SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args, p.prosecdef...
SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args, p.prosecdef AS security_definer, p.proconfig AS settings FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ( 'atomic_place_order', 'atomic_adjust_stock', 'atomic_set_order_status', 'atomic_delete_order', 'zshm_adjust_coupon_usage', 'zshm_order_signature', 'zshm_order_items', 'zshm_order_lines', 'zshm_order_skipped_lines', 'zshm_protect_last_admin', 'zshm_guard_coupon_delete', 'zshm_rate_limit' ) ORDER BY p.proname;

-- 24) SELECT p.oid::regprocedure AS function_signature, pg_get_functiondef(p.oid) AS f...
SELECT p.oid::regprocedure AS function_signature, pg_get_functiondef(p.oid) AS function_definition FROM pg_proc p WHERE p.oid IN ( to_regprocedure('public.atomic_place_order(jsonb,text)'), to_regprocedure('public.atomic_adjust_stock(jsonb,integer)') ) ORDER BY p.proname;

-- 25) SELECT tgname, tgrelid::regclass AS table_name, tgenabled FROM pg_trigger WHERE ...
SELECT tgname, tgrelid::regclass AS table_name, tgenabled FROM pg_trigger WHERE NOT tgisinternal AND tgname IN ('zshm_protect_last_admin', 'zshm_guard_coupon_delete') ORDER BY tgname;

-- 26) SELECT schemaname, relname AS table_name, indexrelname AS index_name, idx_scan, ...
SELECT schemaname, relname AS table_name, indexrelname AS index_name, idx_scan, idx_tup_read, idx_tup_fetch FROM pg_stat_user_indexes WHERE schemaname = 'public' AND relname IN ('products', 'orders') ORDER BY relname, indexrelname;

-- 27) SELECT c.relname, c.relrowsecurity AS rls_enabled, c.relforcerowsecurity AS rls_...
SELECT c.relname, c.relrowsecurity AS rls_enabled, c.relforcerowsecurity AS rls_forced, count(p.policyname) AS policy_count FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace LEFT JOIN pg_policies p ON p.schemaname = n.nspname AND p.tablename = c.relname WHERE n.nspname = 'public' AND c.relname IN ('zshm_deploy_flags', 'zshm_storage_policy_backup') GROUP BY c.relname, c.relrowsecurity, c.relforcerowsecurity ORDER BY c.relname;

-- 28) SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args, p.prosecdef...
SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args, p.prosecdef AS security_definer, p.proconfig AS settings, p.proacl AS grants FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ( 'atomic_place_order', 'atomic_adjust_stock', 'atomic_delete_order', 'atomic_set_order_status', 'atomic_edit_order', 'zshm_order_signature', 'zshm_sellable_stock', 'zshm_order_items', 'zshm_order_lines', 'zshm_order_skipped_lines', 'zshm_valid_variant_stock', 'zshm_adjust_coupon_usage', 'zshm_guard_coupon_delete', 'zshm_protect_last_admin', 'zshm_rate_limit', 'zshm_storage_policy_scope_is_products', 'zshm_restore_storage_policies', 'zshm_refresh_product_rating', 'zshm_product_review_sync_rating', 'handle_new_user_secure' ) ORDER BY p.proname;

-- 29) WITH trg AS ( SELECT t.tgname, t.tgenabled, fn.nspname || '.' || p.proname AS fu...
WITH trg AS ( SELECT t.tgname, t.tgenabled, fn.nspname || '.' || p.proname AS function_name, pg_get_triggerdef(t.oid) AS definition FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace JOIN pg_proc p ON p.oid = t.tgfoid JOIN pg_namespace fn ON fn.oid = p.pronamespace WHERE n.nspname = 'auth' AND c.relname = 'users' AND NOT t.tgisinternal ) SELECT CASE WHEN count(*) FILTER ( WHERE tgenabled = 'O' AND tgname IN ('on_auth_user_created_secure', 'on_auth_user_created') ) = 1 AND count(*) FILTER (WHERE tgenabled <> 'O') = 0 THEN 'PASS' ELSE 'FAIL' END AS verdict, jsonb_agg(jsonb_build_object( 'trigger', tgname, 'function', function_name, 'enabled', tgenabled, 'definition', definition )) AS auth_triggers FROM trg;

-- 30) SELECT tgname, tgrelid::regclass AS table_name, tgenabled FROM pg_trigger WHERE ...
SELECT tgname, tgrelid::regclass AS table_name, tgenabled FROM pg_trigger WHERE NOT tgisinternal AND tgname IN ( 'zshm_protect_last_admin', 'zshm_guard_coupon_delete', 'zshm_product_review_sync' ) ORDER BY tgname;

-- 31) SELECT c.code, COALESCE(c."usageCount", 0) AS usage_count, (SELECT count(*) FROM...
SELECT c.code, COALESCE(c."usageCount", 0) AS usage_count, (SELECT count(*) FROM public.orders o WHERE upper(btrim(COALESCE(o."discountCode", ''))) = upper(c.code) AND lower(COALESCE(o.status, '')) <> 'cancelled') AS active_orders_using_coupon FROM public.coupons c ORDER BY c.code;

-- 32) SELECT id, name, stock, "variantStock" FROM public.products ORDER BY id
SELECT id, name, stock, "variantStock" FROM public.products ORDER BY id;
